mapper.select:
select acm.ai_chat_message_id as aiChatMessageId, acm.ai_chat_session_id as aiChatSessionId, acm.message_role as messageRole, acm.ai_llm_model_id as aiLlmModelId, acm.message_content as messageContent, acm.thinking_content as thinkingContent, acm.result_meta_json as resultMetaJson, acm.create_time as createTime from ai_chat_message acm
and acm.ai_chat_session_id = #{aiChatSessionId}
and acm.message_role = #{messageRole}
and acm.ai_llm_model_id = #{aiLlmModelId}
order by acm.ai_chat_message_id desc

select count(1)
from ai_chat_message acm


        and acm.ai_chat_session_id = #{aiChatSessionId}


        and acm.message_role = #{messageRole}


        and acm.ai_llm_model_id = #{aiLlmModelId}

select acm.ai_chat_message_id, acm.ai_chat_session_id, acm.message_role, acm.ai_llm_model_id, acm.message_content, acm.thinking_content, acm.result_meta_json, acm.create_time from ai_chat_message acm
and acm.ai_chat_session_id = #{aiChatSessionId}
and acm.message_role = #{messageRole}
and acm.ai_llm_model_id = #{aiLlmModelId}
order by acm.ai_chat_message_id desc limit 1

select sub.aiChatMessageId, sub.aiChatSessionId, sub.messageRole, sub.aiLlmModelId, sub.messageContent, sub.thinkingContent, sub.resultMetaJson, sub.createTime from ( select acm.ai_chat_message_id as aiChatMessageId, acm.ai_chat_session_id as aiChatSessionId, acm.message_role as messageRole, acm.ai_llm_model_id as aiLlmModelId, acm.message_content as messageContent, acm.thinking_content as thinkingContent, acm.result_meta_json as resultMetaJson, acm.create_time as createTime from ai_chat_message acm where acm.ai_chat_session_id = #{aiChatSessionId}
and acm.ai_chat_message_id < #{beforeMessageId}
order by acm.ai_chat_message_id desc limit #{limit} ) sub order by sub.aiChatMessageId asc

select count(1)
from ai_chat_message acm
where acm.ai_chat_session_id = #{aiChatSessionId}

select count(1)
from ai_chat_message acm
where acm.ai_chat_session_id = #{aiChatSessionId}
  and acm.ai_chat_message_id < #{beforeMessageId}
